DROP TABLE IF EXISTS `Course`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Course` (
  `university_name` varchar(80) NOT NULL,
  `subject` varchar(8) NOT NULL,
  `number` char(4) NOT NULL,
  `title` varchar(100) NOT NULL,
  PRIMARY KEY (`university_name`,`subject`,`number`),
  CONSTRAINT `fk_course_university` FOREIGN KEY (`university_name`) REFERENCES `University` (`name`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_course_number` CHECK ((`number` between _latin1'1000' and _latin1'9999'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
