--
-- Table structure for table `Develops`
--

DROP TABLE IF EXISTS `Develops`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Develops` (
  `university_name` varchar(80) NOT NULL,
  `subject` varchar(8) NOT NULL,
  `number` char(4) NOT NULL,
  `skill_label` varchar(40) NOT NULL,
  `weight` decimal(3,2) NOT NULL,
  PRIMARY KEY (`university_name`,`subject`,`number`,`skill_label`),
  KEY `ix_develops_skill` (`skill_label`),
  CONSTRAINT `fk_develops_course` FOREIGN KEY (`university_name`, `subject`, `number`) REFERENCES `Course` (`university_name`, `subject`, `number`) ON DELETE CASCADE ON UPDATE CASCADE,
