--
-- Table structure for table `FrozenMember`
--

DROP TABLE IF EXISTS `FrozenMember`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `FrozenMember` (
  `cohort_title` varchar(80) NOT NULL,
  `frozen_at` datetime(6) NOT NULL,
  `handle` varchar(30) NOT NULL,
  `member_no` int NOT NULL,
  PRIMARY KEY (`cohort_title`,`frozen_at`,`handle`),
  UNIQUE KEY `ak_frozenmember_no` (`cohort_title`,`frozen_at`,`member_no`),
  KEY `ix_fm_handle` (`handle`),
  CONSTRAINT `fk_fm_snapshot` FOREIGN KEY (`cohort_title`, `frozen_at`) REFERENCES `CohortSnapshot` (`cohort_title`, `frozen_at`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_fm_student` FOREIGN KEY (`handle`) REFERENCES `Student` (`handle`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_fm_no` CHECK ((`member_no` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

