--
-- Table structure for table `LedgerEntry`
--

DROP TABLE IF EXISTS `LedgerEntry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `LedgerEntry` (
  `handle` varchar(30) NOT NULL,
  `entry_no` int NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `kind` varchar(7) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `trade_market_slug` varchar(60) DEFAULT NULL,
  `trade_created_at` datetime(6) DEFAULT NULL,
  `payout_market_slug` varchar(60) DEFAULT NULL,
  PRIMARY KEY (`handle`,`entry_no`),
  KEY `fk_ledger_trade` (`handle`,`trade_market_slug`,`trade_created_at`),
  KEY `fk_ledger_payout` (`payout_market_slug`),
  CONSTRAINT `fk_ledger_payout` FOREIGN KEY (`payout_market_slug`) REFERENCES `Market` (`slug`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ledger_trade` FOREIGN KEY (`handle`, `trade_market_slug`, `trade_created_at`) REFERENCES `Trade` (`handle`, `market_slug`, `created_at`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_ledger_user` FOREIGN KEY (`handle`) REFERENCES `User` (`handle`) ON DELETE RESTRICT ON UPDATE CASCADE,
