--
-- Table structure for table `Market`
--

DROP TABLE IF EXISTS `Market`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Market` (
  `slug` varchar(60) NOT NULL,
  `question` varchar(200) NOT NULL,
  `metric` varchar(12) NOT NULL,
  `threshold_pct` decimal(5,2) NOT NULL,
  `rule_region` varchar(40) DEFAULT NULL,
  `rule_field` varchar(40) DEFAULT NULL,
  `rule_salary_band` varchar(10) DEFAULT NULL,
  `deadline` date NOT NULL,
  `opens_at` datetime(6) NOT NULL,
  `closes_at` datetime(6) NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'open',
  `outcome` varchar(3) DEFAULT NULL,
  `cohort_title` varchar(80) NOT NULL,
  `frozen_at` datetime(6) NOT NULL,
  PRIMARY KEY (`slug`),
  KEY `fk_market_snapshot` (`cohort_title`,`frozen_at`),
  KEY `ix_market_status` (`status`,`closes_at`),
  CONSTRAINT `fk_market_snapshot` FOREIGN KEY (`cohort_title`, `frozen_at`) REFERENCES `CohortSnapshot` (`cohort_title`, `frozen_at`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_market_metric` CHECK ((`metric` in (_utf8mb4'employed',_utf8mb4'grad_school',_utf8mb4'searching'))),
  CONSTRAINT `ck_market_outcome` CHECK ((((`status` = _utf8mb4'resolved') and (`outcome` in (_utf8mb4'yes',_utf8mb4'no'))) or ((`status` <> _utf8mb4'resolved') and (`outcome` is null)))),
  CONSTRAINT `ck_market_salary` CHECK (((`rule_salary_band` is null) or (`rule_salary_band` in (_utf8mb4'<60k',_utf8mb4'60-80k',_utf8mb4'80-100k',_utf8mb4'100-130k',_utf8mb4'130k+')))),
  CONSTRAINT `ck_market_schedule` CHECK ((`closes_at` > `opens_at`)),
  CONSTRAINT `ck_market_status` CHECK ((`status` in (_utf8mb4'open',_utf8mb4'closed',_utf8mb4'resolved',_utf8mb4'voided'))),
  CONSTRAINT `ck_market_threshold` CHECK (((`threshold_pct` > 0) and (`threshold_pct` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

