DROP TABLE IF EXISTS `MemberOf`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `MemberOf` (
  `handle` varchar(30) NOT NULL,
  `cohort_title` varchar(80) NOT NULL,
  `computed_at` datetime(6) NOT NULL,
  PRIMARY KEY (`handle`,`cohort_title`),
  KEY `ix_memberof_cohort` (`cohort_title`),
  CONSTRAINT `fk_memberof_cohort` FOREIGN KEY (`cohort_title`) REFERENCES `Cohort` (`title`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_memberof_student` FOREIGN KEY (`handle`) REFERENCES `Student` (`handle`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
