--
-- Table structure for table `OutcomeReport`
--

DROP TABLE IF EXISTS `OutcomeReport`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `OutcomeReport` (
  `handle` varchar(30) NOT NULL,
  `reported_at` datetime(6) NOT NULL,
  `status` varchar(12) NOT NULL,
  `job_region` varchar(40) DEFAULT NULL,
  `job_field` varchar(40) DEFAULT NULL,
  `salary_band` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`handle`,`reported_at`),
  KEY `ix_report_status` (`status`,`job_region`),
  CONSTRAINT `fk_report_student` FOREIGN KEY (`handle`) REFERENCES `Student` (`handle`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_report_salary` CHECK (((`salary_band` is null) or ((`status` = _utf8mb4'employed') and (`salary_band` in (_utf8mb4'<60k',_utf8mb4'60-80k',_utf8mb4'80-100k',_utf8mb4'100-130k',_utf8mb4'130k+'))))),
  CONSTRAINT `ck_report_status` CHECK ((`status` in (_utf8mb4'employed',_utf8mb4'searching',_utf8mb4'grad_school',_utf8mb4'other')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

