DROP TABLE IF EXISTS `Position`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Position` (
  `handle` varchar(30) NOT NULL,
  `market_slug` varchar(60) NOT NULL,
  `yes_shares` decimal(10,2) NOT NULL DEFAULT '0.00',
  `no_shares` decimal(10,2) NOT NULL DEFAULT '0.00',
  `cost_basis` decimal(12,2) NOT NULL DEFAULT '0.00',
  `realized_pnl` decimal(12,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`handle`,`market_slug`),
  KEY `fk_position_market` (`market_slug`),
  CONSTRAINT `fk_position_market` FOREIGN KEY (`market_slug`) REFERENCES `Market` (`slug`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_position_user` FOREIGN KEY (`handle`) REFERENCES `User` (`handle`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_position_shares` CHECK (((`yes_shares` >= 0) and (`no_shares` >= 0) and (`cost_basis` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

