DROP TABLE IF EXISTS `Student`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Student` (
  `handle` varchar(30) NOT NULL,
  `program` varchar(60) NOT NULL,
  `grad_year` smallint NOT NULL,
  `verified_at` datetime(6) NOT NULL,
  `consent_at` datetime(6) NOT NULL,
  `university_name` varchar(80) NOT NULL,
  PRIMARY KEY (`handle`),
  KEY `ix_student_university` (`university_name`),
  CONSTRAINT `fk_student_university` FOREIGN KEY (`university_name`) REFERENCES `University` (`name`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_student_user` FOREIGN KEY (`handle`) REFERENCES `User` (`handle`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_student_consent` CHECK ((`consent_at` >= `verified_at`)),
  CONSTRAINT `ck_student_gradyear` CHECK ((`grad_year` between 2000 and 2040))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
