--
-- Table structure for table `Trade`
--

DROP TABLE IF EXISTS `Trade`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Trade` (
  `handle` varchar(30) NOT NULL,
  `market_slug` varchar(60) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `side` varchar(3) NOT NULL,
  `action` varchar(4) NOT NULL,
  `shares` decimal(10,2) NOT NULL,
  `cost` decimal(10,2) NOT NULL,
  `fee` decimal(10,2) NOT NULL,
  `price_after` decimal(5,4) NOT NULL,
  PRIMARY KEY (`handle`,`market_slug`,`created_at`),
  KEY `ix_trade_market_time` (`market_slug`,`created_at`),
  CONSTRAINT `fk_trade_market` FOREIGN KEY (`market_slug`) REFERENCES `Market` (`slug`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_trade_user` FOREIGN KEY (`handle`) REFERENCES `User` (`handle`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_trade_action` CHECK ((`action` in (_utf8mb4'buy',_utf8mb4'sell'))),
  CONSTRAINT `ck_trade_cost` CHECK (((`cost` >= 0) and (`fee` >= 0))),
  CONSTRAINT `ck_trade_price` CHECK (((`price_after` > 0) and (`price_after` < 1))),
  CONSTRAINT `ck_trade_shares` CHECK ((`shares` > 0)),
  CONSTRAINT `ck_trade_side` CHECK ((`side` in (_utf8mb4'yes',_utf8mb4'no')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `Trade`
--

